contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test: when calling buy with tokenIds and tokenWeights and a MerkleMultiProof (which may be empty when merkleRoot==0),
    // the pool transfers out exactly tokenIds.length NFTs (so its NFT balance decreases by that many), and virtualBaseTokenReserves increases by at least the quoted netInputAmount - royalty adjustments are internal but netInputAmount returned from buy includes royalty additions; to observe state we compare nft balance and virtualBaseTokenReserves before/after.
    // Because virtualBaseTokenReserves is public, and NFT balance can be observed via ERC721(nft).balanceOf(address(c)) through c.attributes() or direct call to ERC721, we restrict to observing via C.price() and virtual reserves to avoid non-public members.

    // To keep interactions simple and only use public/external functions, we will call c.virtualBaseTokenReserves() and c.virtualNftReserves() (auto getters), and call buy. We must supply payment amount for ETH-case; pass ethAmount.

    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof_proof, bool[] calldata proof_flags, uint256 ethAmount) public payable {
        // assemble MerkleMultiProof as memory in-place using calldata pieces
        C.MerkleMultiProof memory proof;
        proof.proof = proof_proof; // allowed: calldata to memory copy
        proof.flags = proof_flags;

        // read before-values via public getters
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address nftAddr = c.nft();

        // get NFT balance of pool prior to buy by calling the ERC721 public balanceOf
        uint256 beforeNftBalance = ERC721(nftAddr).balanceOf(address(c));

        // Prepare payable call: if pool uses ETH (baseToken==address(0)) we must forward ethAmount; ensure we have it
        if (address(this).balance < ethAmount) {
            // try to get ETH by reverting early — unreachable in prover; instead require to satisfy template
            require(address(this).balance >= ethAmount);
        }

        // perform buy and capture whether it reverted
        bool reverted = false;
        uint256 netInputAmount = 0;
        uint256 feeAmount = 0;
        uint256 protocolFeeAmount = 0;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // read after-values
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterNftBalance = ERC721(nftAddr).balanceOf(address(c));

        // General invariant to assert:
        // If buy did NOT revert then:
        //   - afterVirtualNft = beforeVirtualNft - sum(tokenWeights)
        //   - afterNftBalance = beforeNftBalance - tokenIds.length
        //   - afterVirtualBase >= beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)  (the contract increases virtualBaseTokenReserves by that amount)
        // We must express sum(tokenWeights) without looping in assert; compute it prior.

        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // Build the boolean condition
        bool cond;
        if (reverted) {
            // If reverted, no observable change in those public getters should have occurred.
            cond = (afterVirtualBase == beforeVirtualBase) && (afterVirtualNft == beforeVirtualNft) && (afterNftBalance == beforeNftBalance);
        } else {
            // Compare NFT counts: guard against underflow by using >= checks rather than subtraction in assert
            bool nftCountOk = (beforeNftBalance >= tokenIds.length) && (afterNftBalance + tokenIds.length == beforeNftBalance);

            // virtualNft decreases by exactly weightSum
            bool vNftOk = (afterVirtualNft + weightSum == beforeVirtualNft);

            // virtualBase increases by at least netInputAmount - feeAmount - protocolFeeAmount
            // compute expectedIncrease = netInputAmount - feeAmount - protocolFeeAmount without underflow risk: require netInputAmount >= fee+protocol
            bool baseIncreaseOk = false;
            if (netInputAmount >= feeAmount + protocolFeeAmount) {
                uint256 expectedInc = netInputAmount - feeAmount - protocolFeeAmount;
                // compare as uint256 to avoid conversion issues
                baseIncreaseOk = (uint256(afterVirtualBase) >= uint256(beforeVirtualBase) + expectedInc);
            }

            cond = nftCountOk && vNftOk && baseIncreaseOk;
        }

        assert(cond);
    }

    receive() external payable {}
}

