        uint256 baseTokenAmount
    ) public payable {
        // Observe public getters before the call
        address nftAddr = c.nft();
        uint256 beforeNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address baseTokenAddr = c.baseToken();
        uint256 beforePoolEth = address(c).balance;

        // If we plan to forward ETH to c, ensure this contract has enough balance
        if (baseTokenAddr == address(0)) {
            require(address(this).balance >= baseTokenAmount);
        }

        // Perform the state-changing call as a top-level statement and capture revert via try/catch
        bool reverted;
        try c.deposit(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterNftBalance = ERC721(nftAddr).balanceOf(address(c));
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterPoolEth = address(c).balance;

        // Build the asserted general rule:
        // If reverted then observable public state must be unchanged (NFT balance and virtual reserves and pool ETH).
        // If succeeded then:
        //  - NFT balance increased by tokenIds.length
        //  - virtual reserves remain equal to before (deposit shouldn't change virtual reserves)
        //  - if baseToken==address(0) then pool ETH increased exactly by baseTokenAmount
        // Note: for ERC20 baseToken we cannot observe ERC20 balances of c reliably here without calling external token contract

        uint256 tokenCount = tokenIds.length;

        if (reverted) {
            assert(
                afterNftBalance == beforeNftBalance
                && afterVirtualBase == beforeVirtualBase
                && afterVirtualNft == beforeVirtualNft
                && afterPoolEth == beforePoolEth
            );
        } else {
            assert(
                afterNftBalance == beforeNftBalance + tokenCount
                && afterVirtualBase == beforeVirtualBase
                && afterVirtualNft == beforeVirtualNft
                && (baseTokenAddr != address(0) || afterPoolEth == beforePoolEth + baseTokenAmount)
            );
        }
    }

    receive() external payable {}
}

