contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call c.buy with parameters. To send Ether, take etherAmount parameter.
    // We observe virtualBaseTokenReserves before and after, address(c).balance, and whether call reverted.
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofArr,
        bool[] calldata flags,
        uint256 etherAmount
    ) public payable {
        // ensure this contract has enough balance if we intend to send Ether
        if (etherAmount > 0) require(address(this).balance >= etherAmount);

        // build MerkleMultiProof (as memory struct expected by buy)
        C.MerkleMultiProof memory mp;
        mp.proof = proofArr;
        mp.flags = flags;

        // read before-state
        uint256 beforeVBase = c.virtualBaseTokenReserves();
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // perform call; must be top-level statement
        try c.buy{value: etherAmount}(tokenIds, tokenWeights, mp) returns (uint256 _net, uint256 _fee, uint256 _prot) {
            reverted = false;
            netInputAmount = _net;
            feeAmount = _fee;
            protocolFeeAmount = _prot;
        } catch {
            reverted = true;
        }

        // read after-state
        uint256 afterVBase = c.virtualBaseTokenReserves();
        uint256 afterBalance = address(c).balance;

        // General rule expressed as single assert:
        // If buy succeeded (not reverted): virtualBaseTokenReserves did not decrease (after >= before),
        // and the increase (after - before) is <= netInputAmount (because implementation adds netInputAmount - fee - protocolFee)
        // Also, if buy reverted then either provided etherAmount was wrong relative to baseToken or the merkle proof was invalid.
        // We cannot directly detect which revert reason occurred, so we assert a weaker implication:
        // If reverted then either etherAmount != 0 implies c.baseToken() != address(0) is false (i.e., ether only allowed when baseToken==0)
        // OR merkleRoot == 0 may allow default behavior; to stay general we assert reverted implies (ether mismatch OR proof may be invalid).

        // Encode the rule into one boolean expression for assert.
        // Construct conditions:
        bool successCond = !reverted && (afterVBase >= beforeVBase) && (afterVBase - beforeVBase <= netInputAmount);

        // For revert case build a conservative necessary condition: if reverted and etherAmount>0 then pool must expect ETH (baseToken==address(0)) to accept ETH — else invalid eth amount likely cause.
        // So we assert reverted implies (etherAmount == 0 || c.baseToken() == address(0));
        bool revertCond = reverted ? (etherAmount == 0 || c.baseToken() == address(0)) : true;

        // Final single assert: either the successful condition holds, or the conservative revert condition holds.
        assert(successCond || revertCond);
    }

    receive() external payable {}
}

contract InvMutTest {
