        // perform the buy call (no ETH forwarded here)
        try c.buy{value: 0}(tokenIds, tokenWeights, mp) returns (uint256 _net, uint256 _fee, uint256 _prot) {
            reverted = false;
            net = _net; fee = _fee; prot = _prot;
        } catch {
            reverted = true;
        }

        // observe after
        uint256 afterVn = c.virtualNftReserves();

        // compute sum of weights in a way safe for calldata lengths <=4
        uint256 sumWeights = 0;
        for (uint i = 0; i < tokenWeights.length; i++) {
            sumWeights += tokenWeights[i];
        }

        // Assert single condition: if succeeded, virtualNftReserves decreased exactly by sumWeights;
