        uint256 sum;
        // We must perform the external call as a top-level statement; use try/catch at top level to observe revert.
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0))) returns (uint256 s) {
            callReverted = false;
            sum = s;
        } catch {
            callReverted = true;
            sum = 0;
        }

        // Single general assertion about the contract behavior when initialized with merkleRoot == 0.
        assert(!callReverted && sum == tokenIds.length * 1e18);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Require a small bounded outputAmount to avoid overflows in the checked environment
    function run(uint256 outputAmount, uint16 feeRate) public payable {
        require(outputAmount > 0 && outputAmount < 1e30, "bad outputAmount");
        require(feeRate <= 5000, "feeRate too high");

        // initialize the pool with sane virtual reserves so buyQuote can compute
        c.initialize(address(0), address(0), uint128(1e18), uint128(1e18 * 2), uint56(0), feeRate, bytes32(0), false, false);

        // call the view to get the quote
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        // General rule: fees are non-negative and netInputAmount is at least feeAmount (i.e., the computed net input covers fees)
        assert(feeAmount + protocolFeeAmount <= netInputAmount && feeAmount <= netInputAmount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint for property test
    function run(uint128 virtualBase, uint128 virtualNft, uint16 feeRate, uint256 outputAmount) public payable {
        // require sensible parameters to avoid division by zero/internal reverts in quotes
        require(outputAmount > 0, "output>0");
        require(virtualNft > outputAmount, "virtualNft>output");
        require(feeRate <= 5000, "feeRate<=5000");

        // initialize the pool (must be called on fresh c). Use msg.sender semantics: this contract owns the pool via Factory in constructor of C in the environment.
        // call initialize which may revert if already initialized; in the test environment c is fresh
        c.initialize(address(0), address(0xdead), virtualBase, virtualNft, 0, feeRate, bytes32(0), false, false);

        // read buyQuote for the given outputAmount
        (uint256 netInputAmount, uint256 feeAmountBuy, uint256 protocolFeeBuy) = c.buyQuote(outputAmount);

        // Use the netInputAmount (which is amount of base token required) as inputAmount to sellQuote to see resulting net output
        (uint256 netOutputAmount, uint256 feeAmountSell, uint256 protocolFeeSell) = c.sellQuote(netInputAmount);

        // General invariant: selling back the netInputAmount obtained from buying 'outputAmount' should not produce strictly more NFTs than the original outputAmount.
        // i.e., netOutputAmount <= outputAmount (no profitable round-trip creating NFTs)
        assert(netOutputAmount <= outputAmount);
    }

    receive() external payable {}
}
